import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Strategy — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"strategy-04-troubleshooting-and-faqs.md","filePath":"strategy-04-troubleshooting-and-faqs.md"}'),n={name:"strategy-04-troubleshooting-and-faqs.md"};function s(i,e,h,l,d,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="strategy-—-troubleshooting-faqs" tabindex="-1">Strategy — Troubleshooting &amp; FAQs <a class="header-anchor" href="#strategy-—-troubleshooting-faqs" aria-label="Permalink to &quot;Strategy — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, misconceptions, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-create-a-strategy" tabindex="-1">Who can create a Strategy? <a class="header-anchor" href="#who-can-create-a-strategy" aria-label="Permalink to &quot;Who can create a Strategy?&quot;">​</a></h3><p>Any workspace member can create a Strategy — it&#39;s not restricted to admins.</p><h3 id="can-a-workspace-have-more-than-one-strategy" tabindex="-1">Can a workspace have more than one Strategy? <a class="header-anchor" href="#can-a-workspace-have-more-than-one-strategy" aria-label="Permalink to &quot;Can a workspace have more than one Strategy?&quot;">​</a></h3><p>Yes. There is no limit on the number of Strategies in a workspace. A common pattern is to maintain both a top-down strategy for executive alignment and a bottom-up strategy grounded in the Feature backlog.</p><h3 id="can-i-change-from-top-down-to-bottom-up-or-vice-versa-after-creating-a-strategy" tabindex="-1">Can I change from top-down to bottom-up (or vice versa) after creating a Strategy? <a class="header-anchor" href="#can-i-change-from-top-down-to-bottom-up-or-vice-versa-after-creating-a-strategy" aria-label="Permalink to &quot;Can I change from top-down to bottom-up (or vice versa) after creating a Strategy?&quot;">​</a></h3><p>No. The approach is chosen at creation and cannot be changed afterward. If you need to switch approaches, create a new Strategy with the desired type.</p><h3 id="can-i-rename-a-strategy-after-creating-it" tabindex="-1">Can I rename a Strategy after creating it? <a class="header-anchor" href="#can-i-rename-a-strategy-after-creating-it" aria-label="Permalink to &quot;Can I rename a Strategy after creating it?&quot;">​</a></h3><p>Yes. Strategy names can be edited at any time.</p><h3 id="can-i-rename-the-three-strategic-dimensions-after-the-strategy-has-been-created" tabindex="-1">Can I rename the three strategic dimensions after the Strategy has been created? <a class="header-anchor" href="#can-i-rename-the-three-strategic-dimensions-after-the-strategy-has-been-created" aria-label="Permalink to &quot;Can I rename the three strategic dimensions after the Strategy has been created?&quot;">​</a></h3><p>Yes. Axis names can be edited at any time, even after the table has been populated. Renaming an axis does not affect the values in the table.</p><h3 id="can-i-add-or-remove-time-intervals-after-the-strategy-has-been-created" tabindex="-1">Can I add or remove time intervals after the Strategy has been created? <a class="header-anchor" href="#can-i-add-or-remove-time-intervals-after-the-strategy-has-been-created" aria-label="Permalink to &quot;Can I add or remove time intervals after the Strategy has been created?&quot;">​</a></h3><p>Yes. Rows can be added or removed at any time. Note that removing a row permanently deletes all values and Feature selections in that interval — there is no undo.</p><h3 id="what-format-do-the-values-take-in-a-top-down-strategy" tabindex="-1">What format do the values take in a top-down strategy? <a class="header-anchor" href="#what-format-do-the-values-take-in-a-top-down-strategy" aria-label="Permalink to &quot;What format do the values take in a top-down strategy?&quot;">​</a></h3><p>Values are plain numbers with no unit. They represent relative emphasis across dimensions within and across intervals — a higher number means more investment in that dimension during that interval. The numbers only mean something relative to each other, so consistency of scale within a strategy matters more than the absolute values.</p><h3 id="can-i-toggle-between-value-and-effort-in-a-top-down-strategy" tabindex="-1">Can I toggle between value and effort in a top-down strategy? <a class="header-anchor" href="#can-i-toggle-between-value-and-effort-in-a-top-down-strategy" aria-label="Permalink to &quot;Can I toggle between value and effort in a top-down strategy?&quot;">​</a></h3><p>No. The value/effort toggle is only available in bottom-up strategies, where cell values are derived from Feature evaluation scores. In top-down strategies, values are manually entered and don&#39;t have a value/effort distinction.</p><h3 id="what-export-formats-are-available-for-strategy" tabindex="-1">What export formats are available for Strategy? <a class="header-anchor" href="#what-export-formats-are-available-for-strategy" aria-label="Permalink to &quot;What export formats are available for Strategy?&quot;">​</a></h3><p>Strategy exports as PPT, Markdown (.md), or HTML (shareable link). The PPT export produces one slide per time interval with a growth cube snapshot; bottom-up strategies also include a Feature list per interval per dimension. The Markdown export produces a structured text version of the strategy, suitable for Notion, Confluence, GitHub, or any Markdown-friendly tool. The HTML export generates a responsive snapshot published to a <code>/share/...</code> URL that anyone can view in a browser without logging in.</p><h3 id="what-happens-to-features-if-i-archive-a-strategy" tabindex="-1">What happens to Features if I archive a Strategy? <a class="header-anchor" href="#what-happens-to-features-if-i-archive-a-strategy" aria-label="Permalink to &quot;What happens to Features if I archive a Strategy?&quot;">​</a></h3><p>Nothing. Features are unaffected by archiving a Strategy. They remain in the Feature backlog as normal. Archiving only removes the Strategy from your active list.</p><h3 id="does-the-growth-cube-animate-automatically" tabindex="-1">Does the growth cube animate automatically? <a class="header-anchor" href="#does-the-growth-cube-animate-automatically" aria-label="Permalink to &quot;Does the growth cube animate automatically?&quot;">​</a></h3><p>Both options are available. You can let it play through automatically or step through intervals manually. Stepping manually is useful when presenting live — it lets you pause and narrate each interval before advancing.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="the-strategy-module-feels-unfamiliar-compared-to-other-strategy-tools" tabindex="-1">The Strategy module feels unfamiliar compared to other strategy tools <a class="header-anchor" href="#the-strategy-module-feels-unfamiliar-compared-to-other-strategy-tools" aria-label="Permalink to &quot;The Strategy module feels unfamiliar compared to other strategy tools&quot;">​</a></h3><p>This is the most common reaction to the Strategy module — it&#39;s intentionally different from conventional strategy artifacts like OKR spreadsheets or strategy decks. The growth cube and the three-dimension constraint are designed to force tradeoffs, not to replicate familiar formats.</p><p>If it feels uncomfortable, that discomfort is often a signal that real tradeoffs are being surfaced. The question to sit with is: if you had to pick only three dimensions, what would they be — and what would you be leaving out?</p><h3 id="my-bottom-up-strategy-cells-are-empty-even-though-i-have-features" tabindex="-1">My bottom-up strategy cells are empty even though I have Features <a class="header-anchor" href="#my-bottom-up-strategy-cells-are-empty-even-though-i-have-features" aria-label="Permalink to &quot;My bottom-up strategy cells are empty even though I have Features&quot;">​</a></h3><p>The most likely cause is that your Features aren&#39;t tagged, or the tags don&#39;t match the dimension mapping. Check that:</p><ul><li>Features in your backlog have tags applied</li><li>The tags match what you&#39;ve mapped to each strategic dimension</li><li>You&#39;re selecting the right tag for each dimension in the strategy setup</li></ul><h3 id="the-growth-cube-looks-the-same-across-all-intervals" tabindex="-1">The growth cube looks the same across all intervals <a class="header-anchor" href="#the-growth-cube-looks-the-same-across-all-intervals" aria-label="Permalink to &quot;The growth cube looks the same across all intervals&quot;">​</a></h3><p>This usually means the values across your intervals are similar or identical. Strategy becomes most interesting when the allocation <em>shifts</em> over time — if your cube isn&#39;t changing, consider whether your strategy is actually articulating a route or just a steady state.</p><h3 id="i-can-t-find-a-strategy-i-previously-created" tabindex="-1">I can&#39;t find a Strategy I previously created <a class="header-anchor" href="#i-can-t-find-a-strategy-i-previously-created" aria-label="Permalink to &quot;I can&#39;t find a Strategy I previously created&quot;">​</a></h3><p>Check whether the Strategy has been archived. Archived Strategies are removed from the active list but are preserved and can be viewed from the archived section.</p><h3 id="the-ppt-export-slides-don-t-have-narrative-text" tabindex="-1">The PPT export slides don&#39;t have narrative text <a class="header-anchor" href="#the-ppt-export-slides-don-t-have-narrative-text" aria-label="Permalink to &quot;The PPT export slides don&#39;t have narrative text&quot;">​</a></h3><p>Narrative text on slides comes from two sources:</p><ul><li><strong>Comment fields</strong> — these must be filled in manually for each time interval before exporting</li><li><strong>AI-generated descriptions</strong> — these must be enabled in the export settings before generating</li></ul><p>If both are empty, the slides will show the growth cube visual only. Add interval comments and/or enable AI generation in the export options to populate the narrative layer.</p><h3 id="my-bottom-up-strategy-shows-very-different-numbers-when-i-toggle-between-value-and-effort" tabindex="-1">My bottom-up strategy shows very different numbers when I toggle between value and effort <a class="header-anchor" href="#my-bottom-up-strategy-shows-very-different-numbers-when-i-toggle-between-value-and-effort" aria-label="Permalink to &quot;My bottom-up strategy shows very different numbers when I toggle between value and effort&quot;">​</a></h3><p>This is expected — and informative. A large gap between value and effort for the same dimension in the same interval means you&#39;re planning to get a lot of value from relatively little effort (or vice versa). These gaps are worth examining: are they realistic? Are they the result of missing evaluation scores on some Features?</p><hr><p><em>This is version 1 of the Strategy documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',46)])])}const g=a(n,[["render",s]]);export{m as __pageData,g as default};
